import unittest
from metrics import rate

class RateTests(unittest.TestCase):
    def test_nonempty(self):
        self.assertEqual(rate(2, 4), 0.5)
    def test_empty(self):
        with self.assertRaises(ValueError):
            rate(1, 0)

if __name__ == "__main__":
    unittest.main()
